// ── Complete Doubly Linked List implementation ─────────────────

class Node {
  constructor(value) {
    this.value = value;
    this.prev = null;
    this.next = null;
  }
}

class DoublyLinkedList {
  constructor() {
    this.head = null;
    this.tail = null;
    this.size = 0;
  }

  // O(1) — update head and neighbour pointer only
  prepend(value) {
    const node = new Node(value);
    if (!this.head) {
      this.head = this.tail = node;
    } else {
      node.next = this.head;
      this.head.prev = node;
      this.head = node;
    }
    this.size++;
    return node; // return reference for O(1) delete later
  }

  // O(1) — tail pointer skips traversal
  append(value) {
    const node = new Node(value);
    if (!this.tail) {
      this.head = this.tail = node;
    } else {
      node.prev = this.tail;
      this.tail.next = node;
      this.tail = node;
    }
    this.size++;
    return node;
  }

  // O(1) — given a direct node reference, no traversal needed
  deleteNode(node) {
    if (node.prev) {
      node.prev.next = node.next;
    } else {
      // node is head
      this.head = node.next;
    }
    if (node.next) {
      node.next.prev = node.prev;
    } else {
      // node is tail
      this.tail = node.prev;
    }
    node.prev = null;
    node.next = null;
    this.size--;
  }

  // O(n) — must walk to find the position
  insertAfter(existingNode, value) {
    if (!existingNode) throw new Error('existingNode required');
    const node = new Node(value);
    node.prev = existingNode;
    node.next = existingNode.next;
    if (existingNode.next) {
      existingNode.next.prev = node;
    } else {
      this.tail = node; // new node is now the tail
    }
    existingNode.next = node;
    this.size++;
    return node;
  }

  // Move an existing node to the front in O(1) — LRU cache trick
  moveToFront(node) {
    if (node === this.head) return;
    this.deleteNode(node);
    node.next = this.head;
    node.prev = null;
    if (this.head) this.head.prev = node;
    this.head = node;
    if (!this.tail) this.tail = node;
    this.size++;
  }

  toArray() {
    const out = [];
    let cur = this.head;
    while (cur) { out.push(cur.value); cur = cur.next; }
    return out;
  }
}

// Demonstration
const list = new DoublyLinkedList();
const nodeA = list.append('A');
const nodeB = list.append('B');
const nodeC = list.append('C');
console.log(list.toArray()); // ['A', 'B', 'C']

list.deleteNode(nodeB);       // O(1) — direct reference
console.log(list.toArray()); // ['A', 'C']

list.insertAfter(nodeA, 'X');
console.log(list.toArray()); // ['A', 'X', 'C']

list.moveToFront(nodeC);      // O(1) — LRU-style promotion
console.log(list.toArray()); // ['C', 'A', 'X']

// ── Big-O comparison table as runnable comments ───────────────
//
// Operation              | Dynamic Array  | Singly Linked  | Doubly Linked
// -----------------------|----------------|----------------|---------------
// Access by index        | O(1)           | O(n)           | O(n)
// Search (unsorted)      | O(n)           | O(n)           | O(n)
// Insert at front        | O(n)  ← shifts | O(1)           | O(1)
// Insert at back         | O(1) amort.    | O(1)*          | O(1)*
// Insert in middle       | O(n)  ← shifts | O(n) + O(1)†  | O(n) + O(1)†
// Delete by index        | O(n)  ← shifts | O(n)           | O(n)
// Delete by reference    | O(n)  ← shifts | O(n) ‡        | O(1) ★
// Memory per element     | 1 word         | 1 word + 1 ptr | 1 word + 2 ptr
// Cache friendliness     | excellent      | poor           | poor
//
// *  O(1) with tail pointer; O(n) without
// †  O(n) traversal to position, then O(1) pointer splice
// ‡  O(n) to find predecessor in singly linked list
// ★  O(1) because prev pointer gives direct predecessor access

// Why doubling gives O(1) amortised — the accounting argument:
function demonstrateAmortisedCost() {
  let copies = 0;
  let capacity = 1;
  let length = 0;
  const N = 1024;

  for (let i = 0; i < N; i++) {
    if (length === capacity) {
      copies += length;    // copy all existing elements
      capacity *= 2;       // double the capacity
    }
    length++;
  }

  console.log(`After ${N} pushes: ${copies} total copy operations`);
  console.log(`Average copies per push: ${(copies / N).toFixed(2)}`);
  // Output: After 1024 pushes: 1023 total copy operations
  //         Average copies per push: 1.00
  // Total copies always < 2N, so amortised O(1)
}

demonstratAmortisedCost();

// Demonstrating O(n) cost of unshift vs O(1) cost of push:
const arr = Array.from({ length: 100000 }, (_, i) => i);

console.time('push x100');
for (let i = 0; i < 100; i++) arr.push(i);
console.timeEnd('push x100');
// fast: O(1) amortised each, no shifting

console.time('unshift x100');
for (let i = 0; i < 100; i++) arr.unshift(i);
console.timeEnd('unshift x100');
// slow: O(n) each — 100,000 elements shift on every call
